<template><view class="ai-product" @click="$emit('click', product)"><image :src="product.image" mode="aspectFit" /><view class="body"><text class="name">{{ product.model }}</text><text class="spec">{{ product.categoryName }} · {{ product.tags.join(' · ') || '参数待补充' }}</text><text class="price">{{ product.priceLabel }}</text></view><up-button size="mini" type="primary" shape="circle" @click.stop="$emit('add', product)">加入报价单</up-button></view></template>
<script setup>defineProps({ product: { type: Object, required: true } }); defineEmits(['click', 'add']);</script>
<style lang="scss" scoped>.ai-product{display:flex;align-items:center;padding:16rpx;margin:12rpx 0;background:#fff;border-radius:16rpx}.ai-product image{width:92rpx;height:92rpx;margin-right:14rpx}.body{flex:1;min-width:0}.name,.spec,.price{display:block}.name{color:#17233d;font-size:25rpx;font-weight:600;/* 产品名称只显示一行，避免挤压右侧加入按钮。 */overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.spec{margin-top:5rpx;color:#8b95a7;font-size:20rpx;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.price{margin-top:7rpx;color:#ef543f;font-size:23rpx}</style>
